const config = $('Configure Multiverse').first().json ?? {};
const state = $('Get NFL State').first().json ?? {};

const leagueId = String(config.leagueId ?? '').trim();
const weekOverride = Number(config.weekOverride ?? 0);
const stateWeek = Number(state.week);

if (!leagueId || leagueId.length > 128) {
  throw new Error('Set Configure Multiverse → leagueId to a valid Sleeper league ID.');
}

const hasOverride = Number.isInteger(weekOverride) && weekOverride >= 1 && weekOverride <= 18;
const targetWeek = hasOverride ? weekOverride : stateWeek;

if (!Number.isInteger(targetWeek) || targetWeek < 1 || targetWeek > 18) {
  throw new Error('Unable to resolve an NFL week. Set weekOverride to a whole number from 1 to 18.');
}

return [{
  json: {
    leagueId,
    targetWeek,
    previousWeek: Math.max(1, targetWeek - 1),
    weekOverride: hasOverride ? weekOverride : 0,
    weekSource: hasOverride ? 'manual override' : 'Sleeper NFL state',
  },
}];

const league = $('Get League').first().json ?? {};
const users = $('Get League Managers').all().map((item) => item.json ?? {});
const rosters = $('Get League Rosters').all().map((item) => item.json ?? {});
const resolved = $('Resolve Target Week').first().json ?? {};

const validMatchups = (items) => items
  .map((item) => item.json ?? {})
  .filter((record) => record.roster_id !== null && record.roster_id !== undefined);

const selectedWeek = validMatchups($('Get Selected Week Matchups').all());
const previousWeek = validMatchups($('Get Previous Week Matchups').all());

const finite = (value, fallback = 0) => {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
};

const hasScoring = (records) => records.some((record) => {
  if (Math.abs(finite(record.points)) > 0.0001) return true;
  const playerPoints = record.players_points && typeof record.players_points === 'object'
    ? Object.values(record.players_points)
    : [];
  return playerPoints.some((points) => Math.abs(finite(points)) > 0.0001);
});

let matchups = selectedWeek;
let analyzedWeek = finite(resolved.targetWeek, 1);
let usedFallback = false;

if (!finite(resolved.weekOverride) && !hasScoring(selectedWeek) && hasScoring(previousWeek)) {
  matchups = previousWeek;
  analyzedWeek = finite(resolved.previousWeek, Math.max(1, analyzedWeek - 1));
  usedFallback = true;
}

if (matchups.length < 2 || !hasScoring(matchups)) {
  return [];
}

const usersById = new Map(
  users
    .filter((user) => user.user_id !== null && user.user_id !== undefined)
    .map((user) => [String(user.user_id), user]),
);

const rostersById = new Map(
  rosters
    .filter((roster) => roster.roster_id !== null && roster.roster_id !== undefined)
    .map((roster) => [String(roster.roster_id), roster]),
);

const teamName = (rosterId) => {
  const roster = rostersById.get(String(rosterId));
  const user = roster ? usersById.get(String(roster.owner_id)) : null;
  return String(
    user?.metadata?.team_name ||
    user?.metadata?.team_name_update ||
    user?.display_name ||
    `Roster ${rosterId}`,
  ).slice(0, 80);
};

const escapeMarkdown = (value) => String(value ?? '')
  .replaceAll('\\', '\\\\')
  .replace(/([`*_~|>#[\]()])/g, '\\$1');

const teams = matchups.map((record) => ({
  rosterId: String(record.roster_id),
  matchupId: record.matchup_id,
  name: teamName(record.roster_id),
  score: Math.round(finite(record.points) * 100) / 100,
  actualResult: 0.5,
  actualLabel: 'BYE',
}));

const groups = new Map();
for (const team of teams) {
  const key = team.matchupId === null || team.matchupId === undefined
    ? `bye-${team.rosterId}`
    : String(team.matchupId);
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(team);
}

const games = [];
for (const group of groups.values()) {
  if (group.length !== 2) continue;
  const [first, second] = group;
  if (first.score > second.score) {
    first.actualResult = 1;
    first.actualLabel = 'W';
    second.actualResult = 0;
    second.actualLabel = 'L';
  } else if (second.score > first.score) {
    second.actualResult = 1;
    second.actualLabel = 'W';
    first.actualResult = 0;
    first.actualLabel = 'L';
  } else {
    first.actualResult = 0.5;
    second.actualResult = 0.5;
    first.actualLabel = 'T';
    second.actualLabel = 'T';
  }
  games.push({
    teams: [first, second],
    margin: Math.abs(first.score - second.score),
  });
}

for (const team of teams) {
  let wins = 0;
  let losses = 0;
  let ties = 0;
  for (const opponent of teams) {
    if (opponent.rosterId === team.rosterId) continue;
    if (team.score > opponent.score) wins += 1;
    else if (team.score < opponent.score) losses += 1;
    else ties += 1;
  }
  const possible = Math.max(1, teams.length - 1);
  team.allPlayWins = wins;
  team.allPlayLosses = losses;
  team.allPlayTies = ties;
  team.expectedWinPct = (wins + (ties * 0.5)) / possible;
  team.luckSwing = (team.actualResult - team.expectedWinPct) * 100;
}

const byScore = [...teams].sort((a, b) => b.score - a.score || a.name.localeCompare(b.name));
const byLuck = [...teams].sort((a, b) => b.luckSwing - a.luckSwing || b.score - a.score);
const realityFavorite = byLuck[0];
const multiverseVictim = byLuck.at(-1);
const timelineChampion = byScore[0];
const closestGame = [...games].sort((a, b) => a.margin - b.margin)[0] ?? null;

const sign = (value) => value > 0 ? '+' : '';
const luckIcon = (value) => value >= 25 ? '🍀' : value <= -25 ? '🕳️' : '⚖️';
const allPlayRecord = (team) => `${team.allPlayWins}-${team.allPlayLosses}${team.allPlayTies ? `-${team.allPlayTies}` : ''}`;

const luckTable = byLuck.map((team, index) =>
  `${index + 1}. ${luckIcon(team.luckSwing)} **${escapeMarkdown(team.name)}** — ${team.actualLabel} | All-play ${allPlayRecord(team)} | **${sign(team.luckSwing)}${team.luckSwing.toFixed(1)} luck**`,
).join('\n');

const matchupLines = games
  .sort((a, b) => a.margin - b.margin)
  .map((game) => {
    const ordered = [...game.teams].sort((a, b) => b.score - a.score);
    const winner = ordered[0];
    const loser = ordered[1];
    const twist = winner.luckSwing >= 25
      ? ' · 🍀 timeline robbery'
      : loser.luckSwing <= -25
        ? ' · 🕳️ multiverse tragedy'
        : '';
    return `**${escapeMarkdown(winner.name)} ${winner.score.toFixed(2)}** — ${escapeMarkdown(loser.name)} ${loser.score.toFixed(2)} · ${game.margin.toFixed(2)}-pt margin${twist}`;
  }).join('\n');

const closestText = closestGame
  ? `${escapeMarkdown(closestGame.teams[0].name)} vs ${escapeMarkdown(closestGame.teams[1].name)} · ${closestGame.margin.toFixed(2)} points`
  : 'No paired matchup returned';

const leagueName = escapeMarkdown(league.name || `Sleeper League ${resolved.leagueId}`);
const fallbackNote = usedFallback
  ? `Sleeper week ${resolved.targetWeek} had no scoring yet, so the portal reopened Week ${analyzedWeek}.`
  : `Analyzing Week ${analyzedWeek}.`;

const payload = {
  username: 'The Multiverse Commissioner',
  content: `🌀 **THE TIMELINE HAS SPLIT** · ${leagueName} · Week ${analyzedWeek}`,
  allowed_mentions: { parse: [] },
  embeds: [
    {
      title: 'Reality is only one possible matchup schedule',
      description: `${teams.length} teams were replayed against every possible opponent. ${fallbackNote}\n\nA win is lucky when most of the league would have beaten you. A loss is cursed when you would have beaten most of the league.`,
      color: 15073081,
      fields: [
        { name: '🌌 Timeline Champion', value: `**${escapeMarkdown(timelineChampion.name)}**\n${timelineChampion.score.toFixed(2)} points`, inline: true },
        { name: '🍀 Reality’s Favorite', value: `**${escapeMarkdown(realityFavorite.name)}**\n${sign(realityFavorite.luckSwing)}${realityFavorite.luckSwing.toFixed(1)} luck`, inline: true },
        { name: '🕳️ Multiverse Victim', value: `**${escapeMarkdown(multiverseVictim.name)}**\n${sign(multiverseVictim.luckSwing)}${multiverseVictim.luckSwing.toFixed(1)} luck`, inline: true },
        { name: '📸 Closest Timeline', value: closestText, inline: false },
      ],
    },
    {
      title: '⚖️ Weekly Luck Index',
      description: luckTable.slice(0, 4096),
      color: 10070709,
    },
    {
      title: '🔀 This Timeline’s Matchups',
      description: matchupLines.slice(0, 4096) || 'No paired matchups were returned.',
      color: 4337850,
      footer: {
        text: 'Public Sleeper data via the unofficial n8n-nodes-sleeper community node · Not affiliated with Sleeper',
      },
      timestamp: new Date().toISOString(),
    },
  ],
};

return [{
  json: {
    ...payload,
    analysis: {
      leagueName: league.name || `Sleeper League ${resolved.leagueId}`,
      analyzedWeek,
      usedFallback,
      teamCount: teams.length,
      realityFavorite: realityFavorite.name,
      multiverseVictim: multiverseVictim.name,
      timelineChampion: timelineChampion.name,
    },
  },
}];
